import {dayNumber} from './age.js';
import {normalizeFamilyHistory} from './family-ledger.js';
export const RECORDS_KEY='ppm-records-v1';
export const DOCUMENT_STATUSES={missing:'Nie przygotowano',prepared:'Przygotowano',submitted:'Złożono',requested:'Zażądano uzupełnienia',supplemented:'Uzupełniono',closed:'Załatwiono'};
export const RECORD_TYPES={persons:'Osoby',children:'Dzieci',relations:'Relacje prawne',insurance:'Tytuły ubezpieczenia',employment:'Zatrudnienie',familyEvents:'Zdarzenia rodzinne',medicalEvents:'Zdarzenia medyczne',applications:'Wnioski',decisions:'Decyzje',periods:'Wykorzystanie uprawnień',payments:'Rzeczywiste wypłaty',documents:'Checklista dokumentów'};
export function createRecordsStore({getStorage=()=>globalThis.localStorage,now=()=>new Date().toISOString(),makeId=()=>globalThis.crypto?.randomUUID?.()||'r-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}={}){
 const empty=()=>({version:1,revision:0,impactRevision:0,records:Object.fromEntries(Object.keys(RECORD_TYPES).map(k=>[k,[]])),audit:[]});
 function read(){const raw=getStorage().getItem(RECORDS_KEY);if(!raw)return empty();const d=JSON.parse(raw);if(d.version!==1||!d.records||Object.keys(RECORD_TYPES).some(k=>!Array.isArray(d.records[k])||d.records[k].length>200))throw new Error('Nieczytelny rejestr spraw — zapis nie został usunięty.');return d;}
 function write(d,action,kind,id){d.revision++;if(!['documents','decisions','payments','applications'].includes(kind))d.impactRevision=(d.impactRevision||0)+1;d.audit=[{at:now(),action,kind,id,revision:d.revision},...(d.audit||[])].slice(0,500);getStorage().setItem(RECORDS_KEY,JSON.stringify(d));}
 function save(kind,value){if(!RECORD_TYPES[kind])throw new Error('Nieznany rodzaj danych.');const d=read(),old=d.records[kind].find(r=>r.id===value.id),item={id:old?.id||makeId(),origin:value.origin==='demo'?'demo':'user',createdAt:old?.createdAt||now(),updatedAt:now(),officiallyVerified:false};
  for(const key of ['name','personId','childId','caseId','documentCode','relation','eventType','occupation','coverage','focus','benefitKind','careType','status','reference','retentionUntil'])if(value[key]!=null)item[key]=String(value[key]).trim().slice(0,key==='name'?200:100);
  for(const key of ['date','start','end','submitted','delivered','finalDate','birthDate'])if(value[key]){dayNumber(value[key]);item[key]=value[key];}
  for(const key of ['grossAmount','netAmount','taxAdvance','healthDeduction','otherDeductions','salary','work','rate'])if(value[key]!==''&&value[key]!=null){const n=Number(value[key]);if(!Number.isFinite(n)||n<0||n>1e9)throw new Error('Sprawdź wpisane kwoty.');item[key]=Math.round((n+Number.EPSILON)*100)/100;}
  if(item.rate!=null&&item.rate>100)throw new Error('Stawka zasiłku nie może przekraczać 100%.');
  if(item.work!=null&&item.work>.5)throw new Error('Łączenie rodzicielskiego z pracą: podaj wymiar do 0,5 pełnego etatu.');
  if(item.start&&item.end&&item.end<item.start)throw new Error('Koniec okresu nie może poprzedzać początku.');if(item.retentionUntil)dayNumber(item.retentionUntil);
  if(!item.name&&!item.documentCode)throw new Error('Podaj nazwę sprawy lub kod dokumentu.');if(kind==='documents'&&!DOCUMENT_STATUSES[item.status])item.status='missing';
  if(old)item.previous=[...(old.previous||[]),Object.fromEntries(Object.entries(old).filter(([k])=>k!=='previous'))].slice(-20);
  if(!old&&d.records[kind].length>=200)throw new Error('Rejestr ma 200 wpisów tego typu. Wyeksportuj i uporządkuj go przed dodaniem następnego.');
  d.records[kind]=[item,...d.records[kind].filter(r=>r.id!==item.id)];write(d,old?'manual-correction':'create',kind,item.id);return item;
 }
 return {snapshot:()=>{try{return {...read(),available:true};}catch(e){return {...empty(),available:false,error:e.message};}},save,remove:(kind,id)=>{const d=read();if(!RECORD_TYPES[kind])throw new Error('Nieznany rodzaj danych.');d.records[kind]=d.records[kind].filter(r=>r.id!==id);write(d,'explicit-delete',kind,id);},export:()=>JSON.stringify(read(),null,2),checkDocument:(caseId,code,status)=>{const d=read(),old=d.records.documents.find(r=>r.caseId===caseId&&r.documentCode===code);return save('documents',{...old,name:code,caseId,documentCode:code,status});}};
}
export function recordsHistory(snapshot){if(!snapshot.available)throw new Error(snapshot.error);const incomplete=snapshot.records.periods.find(p=>!p.personId||!p.start||!p.end||!['planned','requested','approved','used','paid'].includes(p.status)||(['maternity','parental','paternity'].includes(p.benefitKind)&&!p.childId));if(incomplete)throw new Error('Uzupełnij osobę, dziecko, daty i stan wykorzystania w rejestrze: '+incomplete.name+'. Nie traktujemy niepowiązanych okresów jak zerowej historii.');return normalizeFamilyHistory(snapshot.records.periods.map(p=>({rate:p.rate,poolFraction:1-(p.work||0),id:p.id,caseId:'actual-'+p.id,personId:p.personId,childKey:p.childId||'',focus:p.focus||'family',kind:p.benefitKind||'other',careType:p.careType||'',status:p.status,start:p.start,end:p.end})));}
export function compareActualPayment(payment,result){const messages=[],a=payment.start,b=payment.end;if(!a||!b)return {expectedGross:null,difference:null,messages:['Do porównania potrzebny jest okres, którego dotyczy wypłata, a nie tylko dzień przelewu.']};const parent=result.input.formalCase?.personIds?.indexOf(payment.personId);if(!payment.personId||parent==null||parent<0)return {expectedGross:null,difference:null,actualGross:payment.grossAmount??null,actualNet:payment.netAmount??null,messages:['Powiąż wypłatę z tą samą osobą co w scenariuszu. Nie porównujemy jej z łączną kwotą obojga rodziców.']};const periods=result.periods.filter(p=>p.parent===parent&&p.end>=a&&p.start<=b&&p.kind!=='information');let expected=0,known=periods.length>0;for(const p of periods){if(p.daily==null){known=false;continue;}const from=p.start>a?p.start:a,to=p.end<b?p.end:b;expected+=Math.round(p.daily*100)*(dayNumber(to)-dayNumber(from)+1);}const expectedGross=known?expected/100:null;if(payment.netAmount!=null&&payment.grossAmount==null)messages.push('Kwota przelewu jest netto; wynik kalkulatora brutto nie jest bezpośrednio porównywalny.');if(payment.grossAmount!=null&&expectedGross!=null&&payment.grossAmount!==expectedGross)messages.push('Różnica może wynikać z przyznanego okresu, ustalonej podstawy, stawek, korekty, potrąceń lub rozliczenia kilku miesięcy.');if(result.input.dataOrigin==='demo')messages.push('Porównywany scenariusz zawiera dane przykładowe.');messages.push('Sprawdź szczegóły rozliczenia z płatnikiem / ZUS; różnica sama nie dowodzi błędu decyzji.');return {expectedGross,actualGross:payment.grossAmount??null,actualNet:payment.netAmount??null,difference:expectedGross!==null&&payment.grossAmount!=null?Math.round((payment.grossAmount-expectedGross)*100)/100:null,messages};}

export function recordsCalendarEvents(snapshot){if(!snapshot?.available)return [];const labels={submitted:'Złożenie wniosku',delivered:'Doręczenie decyzji',finalDate:'Ostateczność / prawomocność',date:'Data zdarzenia / wypłaty'};return Object.entries(snapshot.records).filter(([kind])=>!['persons','children','relations','documents'].includes(kind)).flatMap(([kind,records])=>records.flatMap(r=>{const anchors=r.start?[['period',r.start,r.end||r.start]]:[];for(const key of Object.keys(labels))if(r[key])anchors.push([key,r[key],r[key]]);return anchors.map(([key,start,end])=>({id:'record-'+kind+'-'+r.id+'-'+key,title:(key==='period'?'':labels[key]+': ')+(r.name||RECORD_TYPES[kind]),start,end,recordKind:kind,recordId:r.id,description:'Wpis z Twojego rejestru: '+RECORD_TYPES[kind]+'. Jest deklaracją z własnych dokumentów, nie potwierdzeniem pobrania danych z urzędu.',source:{id:'personal-record',name:'Twój rejestr',url:''},group:'optional',kind:'Wpis własny',required:false,canMarkNotApplicable:false,informational:true,done:false,notApplicable:false,needsDate:false,important:false}));}));}

export function recordImportFields(snapshot,kind,id){if(!snapshot.available)throw new Error(snapshot.error);const r=snapshot.records[kind]?.find(r=>r.id===id);if(!r||!['insurance','employment','children'].includes(kind))throw new Error('Ten wpis nie ma bezpiecznego mapowania do kalkulatora.');const fields=[];if(kind==='insurance'){for(const key of ['occupation','coverage'])if(r[key])fields.push({field:key,value:r[key]});if(r.start)fields.push({field:'insuranceFrom',value:r.start});if(r.end)fields.push({field:'insuranceTo',value:r.end});}if(kind==='employment'&&r.salary!=null)fields.push({field:'salary',value:r.salary});if(kind==='children'&&r.birthDate)fields.push({field:'childBirthDate',value:r.birthDate});if(!fields.length)throw new Error('W tym wpisie nie ma jeszcze danych do wprowadzenia.');return {importFields:fields,recordPersonId:r.personId||'',recordChildId:kind==='children'?r.id:'',demo:r.origin==='demo',origin:'personal-record'};}
